/*
 * Mireye shape, texture and motion utilities (Tailwind 4). They ship in theme.css. Components compose these; they never redraw them.
 *
 * 1. Trimmed text.	Every Figma text layer uses "Vertical trim: cap height to baseline".
 *		`text-box` does the same in CSS, so a text box is exactly as tall as Figma's.
 *
 * 2. Cut shapes.	The signature 45° chamfer at the top-left. Figma draws it as a path,
 *		e.g. a 256×64 button is	M12 0 H256 V64 H0 V12 L12 0 Z.
 *		- ds-cut				fill only (primary buttons, tags on dark).
 *		- ds-cut-frame	1px border + fill (secondary buttons, fields, cards).
 *		Set the colours with --ds-shape-fill and --ds-shape-stroke, and the size with --ds-cut.
 *
 *		Why the odd decimals on .ds-cut-frame: Figma centres a 1px stroke on a path inset by
 *		0.5px, so the diagonal edge runs along x + y = cut + 0.5. A 1px stroke centred on that
 *		line spans ±0.7071px (half of √2) in x + y terms:
 *			outer edge	x + y = cut − 0.2071	 → the frame's clip-path
 *			inner edge	x + y = cut + 1.2071	 → minus 2 for the 1px inset = cut − 0.7929
 *		With these offsets the diagonal border is exactly 1px wide, like Figma's.
 *
 * 3. Hatch.	A brand texture: 1px vertical lines every 6px, starting 3px in
 *		(Figma: x = 3.5, 9.5, 15.5 … with a 1px stroke). Buttons and map controls draw it on
 *		hover, as in Figma.
 */

/* Utilities, not plain classes, so variants work: `hover:ds-hatch`, `data-[state=hover]:ds-hatch`. */
@utility ds-trim {
	text-box: trim-both cap alphabetic;
}

/*
 * The shape is drawn on pseudo-element layers behind the content, not on the element itself.
 * A clip-path on the element would also clip its focus outline, so keyboard focus would not
 * show on buttons. Layers: ::before = stroke (frame only), ::after = fill + pattern.
 */
@utility ds-cut {
	position: relative;
	isolation: isolate;

	&::after {
		content: "";
		position: absolute;
		inset: 0;
		z-index: -1;
		pointer-events: none;
		background-color: var(--ds-shape-fill, transparent);
		background-image: var(--ds-shape-pattern, none);
		clip-path: polygon(var(--ds-cut) 0, 100% 0, 100% 100%, 0 100%, 0 var(--ds-cut));
	}
}

@utility ds-cut-frame {
	position: relative;
	isolation: isolate;

	&::before {
		content: "";
		position: absolute;
		inset: 0;
		z-index: -1;
		pointer-events: none;
		background-color: var(--ds-shape-stroke, var(--ds-color-border-default));
		clip-path: polygon(
			calc(var(--ds-cut) - 0.2071px) 0,
			100% 0,
			100% 100%,
			0 100%,
			0 calc(var(--ds-cut) - 0.2071px)
		);
	}

	&::after {
		content: "";
		position: absolute;
		inset: var(--ds-border-width);
		z-index: -1;
		pointer-events: none;
		background-color: var(--ds-shape-fill, var(--ds-color-bg-default));
		background-image: var(--ds-shape-pattern, none);
		/* Keep the pattern on the outer box's grid, so lines sit where Figma puts them. */
		background-position: calc(-1 * var(--ds-border-width)) 0;
		clip-path: polygon(
			calc(var(--ds-cut) - 0.7929px) 0,
			100% 0,
			100% 100%,
			0 100%,
			0 calc(var(--ds-cut) - 0.7929px)
		);
	}
}

@utility ds-hatch {
	--ds-shape-pattern: repeating-linear-gradient(
