/*
 * Scroll edges fade, never cut content off: an edge with more content past it fades over 24px. The fade grows
 * with the first and last 24px of scroll (tied to the scroll, not to time), so a list at rest shows its first row
 * in full and a list that does not scroll has no fade. Browsers without scroll timelines get a short fixed fade.
 * `fade-y` on a box that scrolls vertically, `fade-x` on one that scrolls sideways, `fade-xy` on one that scrolls
 * both ways (a code block). The mask color only needs to be opaque; it never shows.
 */
@property --fade-start {
	syntax: "<length>";
	inherits: false;
	initial-value: 0px;
}

@property --fade-end {
	syntax: "<length>";
	inherits: false;
	initial-value: 0px;
}

@property --fade-x-start {
	syntax: "<length>";
	inherits: false;
	initial-value: 0px;
}

@property --fade-x-end {
	syntax: "<length>";
	inherits: false;
	initial-value: 0px;
}

@keyframes fade-start {
	from {
		--fade-start: 0px;
	}
	to {
		--fade-start: 24px;
	}
}

@keyframes fade-end {
	from {
		--fade-end: 24px;
	}
	to {
		--fade-end: 0px;
	}
}

@keyframes fade-x-start {
	from {
		--fade-x-start: 0px;
	}
	to {
		--fade-x-start: 24px;
	}
}

@keyframes fade-x-end {
	from {
		--fade-x-end: 24px;
	}
	to {
		--fade-x-end: 0px;
	}
}

@utility fade-y {
	mask-image: linear-gradient(to bottom, transparent, black var(--fade-start), black calc(100% - var(--fade-end)), transparent);

	@supports (animation-timeline: scroll()) {
		animation: fade-start linear both, fade-end linear both;
		animation-timeline: scroll(self block), scroll(self block);
		animation-range: 0px 24px, calc(100% - 24px) 100%;
	}

	@supports not (animation-timeline: scroll()) {
		--fade-start: 8px;
		--fade-end: 8px;
	}
}

@utility fade-x {
	mask-image: linear-gradient(to right, transparent, black var(--fade-start), black calc(100% - var(--fade-end)), transparent);

	@supports (animation-timeline: scroll()) {
		animation: fade-start linear both, fade-end linear both;
		animation-timeline: scroll(self inline), scroll(self inline);
		animation-range: 0px 24px, calc(100% - 24px) 100%;
	}

	@supports not (animation-timeline: scroll()) {
		--fade-start: 8px;
		--fade-end: 8px;
	}
}

@utility fade-xy {
	mask-image: linear-gradient(to bottom, transparent, black var(--fade-start), black calc(100% - var(--fade-end)), transparent), linear-gradient(to right, transparent, black var(--fade-x-start), black calc(100% - var(--fade-x-end)), transparent);
	mask-composite: intersect;

	@supports (animation-timeline: scroll()) {
		animation: fade-start linear both, fade-end linear both, fade-x-start linear both, fade-x-end linear both;
		animation-timeline: scroll(self block), scroll(self block), scroll(self inline), scroll(self inline);
		animation-range: 0px 24px, calc(100% - 24px) 100%, 0px 24px, calc(100% - 24px) 100%;
	}

	@supports not (animation-timeline: scroll()) {
		--fade-start: 8px;
		--fade-end: 8px;
		--fade-x-start: 8px;
		--fade-x-end: 8px;
	}
}

/*
 * A row that scrolls sideways under a sticky first column (compare-matrix). `fade-x-end` on the scroller fades only
 * its end edge and names its scroll (--fade-x) for the column inside. `fade-under` on the sticky cells shows their
 * trailing shade (their ::after, drawn by the component) with the first 24px of scroll, so cells fade under the
 * column instead of being sliced. Without scroll timelines, or under reduced motion, the component's own scrolled
 * state shows the shade.
 */
@keyframes fade-under {
	from {
		opacity: 0;
	}
	to {
		opacity: 1;
	}
}

@utility fade-x-end {
	scroll-timeline: --fade-x inline;
	mask-image: linear-gradient(to right, black calc(100% - var(--fade-x-end)), transparent);

	@supports (animation-timeline: scroll()) {
		animation: fade-x-end linear both;
		animation-timeline: --fade-x;
		animation-range: calc(100% - 24px) 100%;
	}

	@supports not (animation-timeline: scroll()) {
		--fade-x-end: 8px;
	}
}

@utility fade-under {
	@supports (animation-timeline: scroll()) {
		&::after {
			animation: fade-under linear both;
			animation-timeline: --fade-x;
			animation-range: 0px 24px;
		}
	}
}

/* Shared interaction rules for installed CSS and the component theme. */
@layer base {
 :where(button, [role="button"], a[href], input, select, textarea, summary) {
  touch-action: manipulation;
 }
}

/* Press feedback is immediate; the action still activates through the native click/keyboard path. */
:where(button, [role="button"], a[href], summary):active {
 transition-duration: 0s !important;
 transition-delay: 0s !important;
}

/* Keyboard feedback and explicitly high-frequency surfaces never wait for motion. The scroll edge fades (fade-y,
   fade-x, fade-xy) are exempt here and under reduced motion: they follow the scroll position, not time, and without
   them content is cut off by a hard edge. */
:where(button, [role="button"], a[href], input, select, textarea, summary):focus-visible:where(:not(.fade-y, .fade-x, .fade-xy, .fade-x-end, [class*=":fade-x"], [class*=":fade-y"])),
:where(button, [role="button"], a[href], input, select, textarea, summary):focus-visible *:where(:not(.fade-y, .fade-x, .fade-xy, .fade-x-end, [class*=":fade-x"], [class*=":fade-y"])),
:where([data-ds-motion="instant"], [data-instant="true"], [data-slot^="command"]):where(:not(.fade-y, .fade-x, .fade-xy, .fade-x-end, [class*=":fade-x"], [class*=":fade-y"])),
:where([data-ds-motion="instant"], [data-instant="true"], [data-slot^="command"]) *:where(:not(.fade-y, .fade-x, .fade-xy, .fade-x-end, [class*=":fade-x"], [class*=":fade-y"])),
:where([data-ds-motion="instant"], [data-instant="true"], [data-slot^="command"]) *::before,
:where([data-ds-motion="instant"], [data-instant="true"], [data-slot^="command"]) *::after,
:where([data-ds-motion="instant"], [data-instant="true"], [data-slot^="command"])::before,
:where([data-ds-motion="instant"], [data-instant="true"], [data-slot^="command"])::after {
 animation: none !important;
 transition: none !important;
 scroll-behavior: auto !important;
}

@media (prefers-reduced-motion: reduce) {
 *:where(:not(.fade-y, .fade-x, .fade-xy, .fade-x-end, [class*=":fade-x"], [class*=":fade-y"])), ::before, ::after {
